import{_ as p}from"./plugin-vue_export-helper-c27b6911.js";import{r as c,o,c as i,d as s,e as n,b as e,w as t,a as l,f as d}from"./app-31ccb12c.js";const u={},r=s("p",null,[n("从 SoC 的 I2S 引脚一路讲到 "),s("code",null,"/dev/snd"),n("：ASoC 三件套、DAPM、设备树、ALSA 的 period/buffer、asound.conf 和常用调试命令。")],-1),k=s("p",null,"文末有一份可直接编译运行的 ALSA 采集代码，以及一套「没声音」的排查顺序。",-1),m=d(`<h2 id="_3-linux-音频技术栈" tabindex="-1"><a class="header-anchor" href="#_3-linux-音频技术栈" aria-hidden="true">#</a> 3. Linux 音频技术栈</h2><p>Linux 音频栈可以按「硬件 → 驱动 → 内核框架 → 用户态库/服务 → 应用」五层理解。面试最容易被追问的是 <strong>ASoC 三件套、DAPM、period/buffer、xrun 恢复</strong>。</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>应用（ASR/播放器/通话）
   │  ALSA-lib / PulseAudio / PipeWire / GStreamer / tinyalsa
   ▼
ALSA 内核（snd-pcm / snd-ctl / snd-seq）
   │
ASoC（machine / platform / codec）+ DAPM
   │
I2S/TDM/PDM/SoundWire 控制器 + DMA + Codec + 功放
   │
麦克风 / 扬声器
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-1-硬件层-soc、codec、功放与-dma" tabindex="-1"><a class="header-anchor" href="#_3-1-硬件层-soc、codec、功放与-dma" aria-hidden="true">#</a> 3.1 硬件层：SoC、Codec、功放与 DMA</h3><p>典型智能音箱/会议设备的音频硬件：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>4× MEMS MIC (PDM) ──┐
                    ├─→ SoC PDM 控制器 ─→ 抽取滤波 ─→ DMA ─→ 内存
Codec (ES8316/NAU88C10/RT5651/TLV320AIC)
   ├─ ADC ← 模拟麦 / 线路输入
   ├─ DAC → 功放 (AW8896/TAS5805/MAX98357A) → 扬声器
   └─ I2S/TDM ←→ SoC I2S 控制器
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键硬件参数：</p><ul><li><strong>MEMS 麦克风</strong>：SNR 60—70 dB、AOP 120—130 dBSPL、灵敏度 -38 ~ -26 dBV/Pa、PDM 时钟 1—3 MHz。</li><li><strong>Codec</strong>：ADC/DAC SNR、THD+N、PGA 范围、MCLK 支持范围（通常 256/384/512 fs）、是否内置 DSP。</li><li><strong>功放</strong>：Class-D 效率高但有 EMI；需要看电源抑制比（PSRR）、pop 抑制、过流保护。</li><li><strong>DMA</strong>：分散/聚集（scatter-gather）、循环缓冲、双缓冲半满/全满中断。</li><li><strong>DSP</strong>：HiFi/Hexagon/CEVA 核，用于 offload AEC/NS/唤醒词，节省主核功耗。</li></ul><p>硬件设计对软件的影响：</p><ul><li>MCLK 走线/时钟源不稳 → 采样率偏差、爆音。</li><li>模拟麦偏置与地线布局 → 底噪、hum。</li><li>功放使能 GPIO 时序 → 上电 pop。</li><li>PDM 时钟与 I2S 共用 PLL → 改采样率时可能无 clock。</li></ul><h3 id="_3-2-驱动层-asoc-架构" tabindex="-1"><a class="header-anchor" href="#_3-2-驱动层-asoc-架构" aria-hidden="true">#</a> 3.2 驱动层：ASoC 架构</h3><p>ASoC（ALSA System on Chip）把音频驱动拆成三个可复用的部分：</p><table><thead><tr><th>组件</th><th>职责</th><th>典型代码位置</th></tr></thead><tbody><tr><td><strong>Machine</strong></td><td>描述「哪块板子、哪个 CPU DAI 接哪个 Codec DAI」，定义 card、dai_link、widgets/routes、板级 ops</td><td><code>sound/soc/&lt;vendor&gt;/&lt;board&gt;.c</code></td></tr><tr><td><strong>Platform</strong></td><td>SoC 侧的 I2S/TDM 控制器 + DMA（<code>snd_dmaengine_pcm</code>）</td><td><code>sound/soc/&lt;vendor&gt;/&lt;i2s&gt;.c</code></td></tr><tr><td><strong>Codec</strong></td><td>Codec 寄存器、时钟、DAPM、kcontrol、DAI ops</td><td><code>sound/soc/codecs/&lt;codec&gt;.c</code></td></tr></tbody></table><p><strong>DAI（Digital Audio Interface）</strong>：CPU DAI 与 Codec DAI 通过 <code>dai_link</code> 连接，双方用 <code>set_fmt</code> 协商格式（I2S/左对齐/DSP、主从、时钟极性）。</p><p><strong>DAPM（Dynamic Audio Power Management）</strong>：</p><ul><li>把 codec 内部和板级路径抽象成 <strong>widget</strong>（mux、mixer、PGA、ADC、DAC、AIF、MIC、SPK、regulator）和 <strong>route</strong>（连接关系）。</li><li>根据当前活跃的 PCM 流，自动上电/下电整条路径，并在顺序上做 pop 抑制。</li><li>调试入口：<code>/sys/kernel/debug/asoc/&lt;card&gt;/dapm</code>。</li></ul><p><strong>Kcontrol</strong>：用户态可见的控件（音量、mux、EQ），用 <code>SOC_SINGLE</code>/<code>SOC_DOUBLE_R</code>/<code>SOC_ENUM</code>/<code>SOC_SINGLE_TLV</code> 定义，<code>amixer</code> 直接操作。</p><p><strong>Runtime PM / regmap</strong>：codec 寄存器通过 regmap 访问，支持 cache；suspend/resume 时恢复。</p><p><strong>Jack 检测</strong>：<code>snd_soc_jack</code> + <code>snd_jack</code>，耳机插入/拔出上报到用户态。</p><p><strong>Probe 顺序</strong>（简化）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>platform_driver probe → 注册 CPU DAI / DMA
codec i2c probe       → 注册 component / DAI / kcontrols / DAPM
machine probe         → 绑定 dai_link → snd_soc_register_card()
                      → 创建 card、pcm 设备 → /dev/snd/pcmC0D0p 出现
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>hw_params 阶段要做的事</strong>：</p><ul><li>根据 rate 设置 codec 的 sysclk/PLL（MCLK = 256/384/512 × fs）。</li><li>设置 I2S 的 slot 宽度、帧格式、主从。</li><li>设置 codec 的采样率、静音/去加重。</li><li>失败要回滚，避免 clock 开着但没流。</li></ul><p><strong>trigger 阶段</strong>：<code>SNDRV_PCM_TRIGGER_START/STOP/PAUSE</code> 控制 DMA 启停，注意 start 前先清 FIFO。</p><p><strong>常见驱动问题</strong>：</p><table><thead><tr><th>现象</th><th>可能原因</th></tr></thead><tbody><tr><td>完全没声音</td><td>DAPM route 缺失、codec 未上电、MCLK 没开、I2S 主从冲突</td></tr><tr><td>声音音调不对</td><td>MCLK/BCLK 比率错、采样率不匹配、TDM slot 宽度错</td></tr><tr><td>只有一边声道</td><td>slot 映射错、声道交换、功放单声道配置</td></tr><tr><td>pop/click</td><td>上电时序、PGA 突变、功放 EN 与 I2S 启动顺序</td></tr><tr><td>录音全是噪声</td><td>格式/端序错、PDM 时钟错、模拟增益过大</td></tr><tr><td>录音很小</td><td>PGA 太小、麦克风偏置未开、单端/差分接错</td></tr></tbody></table><h3 id="_3-3-设备树与驱动代码骨架" tabindex="-1"><a class="header-anchor" href="#_3-3-设备树与驱动代码骨架" aria-hidden="true">#</a> 3.3 设备树与驱动代码骨架</h3><p><strong>设备树（simple-audio-card）</strong>：</p><div class="language-dts line-numbers-mode" data-ext="dts"><pre class="language-dts"><code>sound {
    compatible = &quot;simple-audio-card&quot;;
    simple-audio-card,name = &quot;my-soc-sound&quot;;
    simple-audio-card,format = &quot;i2s&quot;;
    simple-audio-card,bitclock-master = &lt;&amp;dailink_master&gt;;
    simple-audio-card,frame-master     = &lt;&amp;dailink_master&gt;;

    dailink_master: simple-audio-card,cpu {
        sound-dai = &lt;&amp;i2s0&gt;;
    };
    simple-audio-card,codec {
        sound-dai = &lt;&amp;codec&gt;;
    };
};

&amp;i2s0 {
    status = &quot;okay&quot;;
    pinctrl-names = &quot;default&quot;;
    pinctrl-0 = &lt;&amp;i2s0_mclk &amp;i2s0_bclk &amp;i2s0_lrck &amp;i2s0_sdi &amp;i2s0_sdo&gt;;
};
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>要点：</p><ul><li><code>bitclock-master</code> / <code>frame-master</code> 的 phandle 指向 <strong>CPU 或 Codec 的子节点</strong>（上例给 CPU 节点打了 <code>dailink_master</code> 标签），不是指向声卡节点。</li><li><code>format</code> 可选 <code>i2s</code>、<code>right_j</code>、<code>left_j</code>、<code>dsp_a</code>、<code>dsp_b</code>。</li><li>多声道用 <code>dai-tdm-slot-num</code> / <code>dai-tdm-slot-width</code>。</li><li>MCLK 通常由 <code>assigned-clocks</code>/<code>assigned-clock-rates</code> 或 codec 节点里的 <code>clocks</code>/<code>clock-names</code> 指定。</li></ul><p><strong>Codec DAI ops 骨架</strong>：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">static</span> <span class="token keyword">int</span> <span class="token function">my_codec_hw_params</span><span class="token punctuation">(</span><span class="token keyword">struct</span> <span class="token class-name">snd_pcm_substream</span> <span class="token operator">*</span>substream<span class="token punctuation">,</span>
                              <span class="token keyword">struct</span> <span class="token class-name">snd_pcm_hw_params</span> <span class="token operator">*</span>params<span class="token punctuation">,</span>
                              <span class="token keyword">struct</span> <span class="token class-name">snd_soc_dai</span> <span class="token operator">*</span>dai<span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">struct</span> <span class="token class-name">snd_soc_component</span> <span class="token operator">*</span>comp <span class="token operator">=</span> dai<span class="token operator">-&gt;</span>component<span class="token punctuation">;</span>
    <span class="token comment">/* priv-&gt;mclk 在 probe 里 devm_clk_get() 得到 */</span>
    <span class="token keyword">struct</span> <span class="token class-name">my_codec</span> <span class="token operator">*</span>priv <span class="token operator">=</span> <span class="token function">snd_soc_component_get_drvdata</span><span class="token punctuation">(</span>comp<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">unsigned</span> <span class="token keyword">int</span> rate  <span class="token operator">=</span> <span class="token function">params_rate</span><span class="token punctuation">(</span>params<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">unsigned</span> <span class="token keyword">int</span> width <span class="token operator">=</span> <span class="token function">params_width</span><span class="token punctuation">(</span>params<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">int</span> mclk<span class="token punctuation">;</span>

    <span class="token keyword">switch</span> <span class="token punctuation">(</span>rate<span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token keyword">case</span> <span class="token number">8000</span><span class="token operator">:</span>  mclk <span class="token operator">=</span> <span class="token number">2048000</span><span class="token punctuation">;</span>  <span class="token keyword">break</span><span class="token punctuation">;</span>
    <span class="token keyword">case</span> <span class="token number">16000</span><span class="token operator">:</span> mclk <span class="token operator">=</span> <span class="token number">4096000</span><span class="token punctuation">;</span>  <span class="token keyword">break</span><span class="token punctuation">;</span>
    <span class="token keyword">case</span> <span class="token number">44100</span><span class="token operator">:</span> mclk <span class="token operator">=</span> <span class="token number">11289600</span><span class="token punctuation">;</span> <span class="token keyword">break</span><span class="token punctuation">;</span>
    <span class="token keyword">case</span> <span class="token number">48000</span><span class="token operator">:</span> mclk <span class="token operator">=</span> <span class="token number">12288000</span><span class="token punctuation">;</span> <span class="token keyword">break</span><span class="token punctuation">;</span>
    <span class="token keyword">default</span><span class="token operator">:</span>    <span class="token keyword">return</span> <span class="token operator">-</span>EINVAL<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token function">clk_set_rate</span><span class="token punctuation">(</span>priv<span class="token operator">-&gt;</span>mclk<span class="token punctuation">,</span> mclk<span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token comment">/* 字长；协议（I2S/左对齐）与主从在 set_fmt 里设置 */</span>
    <span class="token function">snd_soc_component_update_bits</span><span class="token punctuation">(</span>comp<span class="token punctuation">,</span> MY_REG_FMT<span class="token punctuation">,</span> <span class="token number">0x1f</span><span class="token punctuation">,</span>
                                  <span class="token function">width_to_reg</span><span class="token punctuation">(</span>width<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token comment">/* 设置采样率相关分频 */</span>
    <span class="token function">snd_soc_component_write</span><span class="token punctuation">(</span>comp<span class="token punctuation">,</span> MY_REG_SR<span class="token punctuation">,</span> <span class="token function">rate_to_reg</span><span class="token punctuation">(</span>rate<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> <span class="token number">0</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">static</span> <span class="token keyword">const</span> <span class="token keyword">struct</span> <span class="token class-name">snd_soc_dai_ops</span> my_codec_dai_ops <span class="token operator">=</span> <span class="token punctuation">{</span>
    <span class="token punctuation">.</span>hw_params <span class="token operator">=</span> my_codec_hw_params<span class="token punctuation">,</span>
    <span class="token punctuation">.</span>set_fmt   <span class="token operator">=</span> my_codec_set_fmt<span class="token punctuation">,</span>
    <span class="token punctuation">.</span>trigger   <span class="token operator">=</span> my_codec_trigger<span class="token punctuation">,</span>
    <span class="token punctuation">.</span>mute_stream <span class="token operator">=</span> my_codec_mute<span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token keyword">static</span> <span class="token keyword">struct</span> <span class="token class-name">snd_soc_dai_driver</span> my_codec_dai <span class="token operator">=</span> <span class="token punctuation">{</span>
    <span class="token punctuation">.</span>name <span class="token operator">=</span> <span class="token string">&quot;my-codec-hifi&quot;</span><span class="token punctuation">,</span>
    <span class="token punctuation">.</span>playback <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span>stream_name <span class="token operator">=</span> <span class="token string">&quot;Playback&quot;</span><span class="token punctuation">,</span> <span class="token punctuation">.</span>channels_min <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">,</span>
                  <span class="token punctuation">.</span>channels_max <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token punctuation">.</span>rates <span class="token operator">=</span> SNDRV_PCM_RATE_8000_48000<span class="token punctuation">,</span>
                  <span class="token punctuation">.</span>formats <span class="token operator">=</span> SNDRV_PCM_FMTBIT_S16_LE <span class="token operator">|</span> SNDRV_PCM_FMTBIT_S24_LE <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">.</span>capture  <span class="token operator">=</span> <span class="token punctuation">{</span> <span class="token punctuation">.</span>stream_name <span class="token operator">=</span> <span class="token string">&quot;Capture&quot;</span><span class="token punctuation">,</span>  <span class="token punctuation">.</span>channels_min <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">,</span>
                  <span class="token punctuation">.</span>channels_max <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">,</span> <span class="token punctuation">.</span>rates <span class="token operator">=</span> SNDRV_PCM_RATE_8000_48000<span class="token punctuation">,</span>
                  <span class="token punctuation">.</span>formats <span class="token operator">=</span> SNDRV_PCM_FMTBIT_S16_LE <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">.</span>ops <span class="token operator">=</span> <span class="token operator">&amp;</span>my_codec_dai_ops<span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Machine driver 关键结构</strong>：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token function">SND_SOC_DAILINK_DEFS</span><span class="token punctuation">(</span>my_link<span class="token punctuation">,</span>
    <span class="token function">DAILINK_COMP_ARRAY</span><span class="token punctuation">(</span><span class="token function">COMP_CPU</span><span class="token punctuation">(</span><span class="token string">&quot;i2s0&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token function">DAILINK_COMP_ARRAY</span><span class="token punctuation">(</span><span class="token function">COMP_CODEC</span><span class="token punctuation">(</span><span class="token string">&quot;1-0018&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;my-codec-hifi&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token function">DAILINK_COMP_ARRAY</span><span class="token punctuation">(</span><span class="token function">COMP_PLATFORM</span><span class="token punctuation">(</span><span class="token string">&quot;dma&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token keyword">static</span> <span class="token keyword">struct</span> <span class="token class-name">snd_soc_dai_link</span> my_dai_links<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">{</span>
    <span class="token punctuation">{</span>
        <span class="token punctuation">.</span>name <span class="token operator">=</span> <span class="token string">&quot;my-hifi&quot;</span><span class="token punctuation">,</span>
        <span class="token punctuation">.</span>stream_name <span class="token operator">=</span> <span class="token string">&quot;HiFi&quot;</span><span class="token punctuation">,</span>
        <span class="token punctuation">.</span>dai_fmt <span class="token operator">=</span> SND_SOC_DAIFMT_I2S <span class="token operator">|</span> SND_SOC_DAIFMT_NB_NF <span class="token operator">|</span>
                   SND_SOC_DAIFMT_CBS_CFS<span class="token punctuation">,</span>
        <span class="token function">SND_SOC_DAILINK_REG</span><span class="token punctuation">(</span>my_link<span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token punctuation">}</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token keyword">static</span> <span class="token keyword">struct</span> <span class="token class-name">snd_soc_card</span> my_card <span class="token operator">=</span> <span class="token punctuation">{</span>
    <span class="token punctuation">.</span>name <span class="token operator">=</span> <span class="token string">&quot;my-soc-sound&quot;</span><span class="token punctuation">,</span>
    <span class="token punctuation">.</span>owner <span class="token operator">=</span> THIS_MODULE<span class="token punctuation">,</span>
    <span class="token punctuation">.</span>dai_link <span class="token operator">=</span> my_dai_links<span class="token punctuation">,</span>
    <span class="token punctuation">.</span>num_links <span class="token operator">=</span> <span class="token function">ARRAY_SIZE</span><span class="token punctuation">(</span>my_dai_links<span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token punctuation">.</span>dapm_widgets <span class="token operator">=</span> my_widgets<span class="token punctuation">,</span>
    <span class="token punctuation">.</span>num_dapm_widgets <span class="token operator">=</span> <span class="token function">ARRAY_SIZE</span><span class="token punctuation">(</span>my_widgets<span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token punctuation">.</span>dapm_routes <span class="token operator">=</span> my_routes<span class="token punctuation">,</span>
    <span class="token punctuation">.</span>num_dapm_routes <span class="token operator">=</span> <span class="token function">ARRAY_SIZE</span><span class="token punctuation">(</span>my_routes<span class="token punctuation">)</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>DAPM widget/route 示例</strong>：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token keyword">static</span> <span class="token keyword">const</span> <span class="token keyword">struct</span> <span class="token class-name">snd_soc_dapm_widget</span> my_widgets<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">{</span>
    <span class="token function">SND_SOC_DAPM_SPK</span><span class="token punctuation">(</span><span class="token string">&quot;Speaker&quot;</span><span class="token punctuation">,</span> <span class="token constant">NULL</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token function">SND_SOC_DAPM_MIC</span><span class="token punctuation">(</span><span class="token string">&quot;Mic&quot;</span><span class="token punctuation">,</span> <span class="token constant">NULL</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token function">SND_SOC_DAPM_OUTPUT</span><span class="token punctuation">(</span><span class="token string">&quot;SPK_OUT&quot;</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>

<span class="token keyword">static</span> <span class="token keyword">const</span> <span class="token keyword">struct</span> <span class="token class-name">snd_soc_dapm_route</span> my_routes<span class="token punctuation">[</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token punctuation">{</span>
    <span class="token punctuation">{</span> <span class="token string">&quot;Speaker&quot;</span><span class="token punctuation">,</span> <span class="token constant">NULL</span><span class="token punctuation">,</span> <span class="token string">&quot;SPK_OUT&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
    <span class="token punctuation">{</span> <span class="token string">&quot;SPK_OUT&quot;</span><span class="token punctuation">,</span> <span class="token constant">NULL</span><span class="token punctuation">,</span> <span class="token string">&quot;HPOUTL&quot;</span> <span class="token punctuation">}</span><span class="token punctuation">,</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-4-alsa-用户态编程" tabindex="-1"><a class="header-anchor" href="#_3-4-alsa-用户态编程" aria-hidden="true">#</a> 3.4 ALSA 用户态编程</h3><p><strong>对象层级</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>snd_card → snd_pcm (device) → substream → hw_params / sw_params / status
         → snd_ctl (controls)
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>设备节点：<code>/dev/snd/pcmC0D0p</code>（card0 device0 playback）、<code>pcmC0D0c</code>（capture）、<code>controlC0</code>。</p><p><strong>PCM 状态机</strong>：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>OPEN → SETUP → PREPARED → RUNNING → (XRUN / DRAINING / PAUSED) → SETUP
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>period 与 buffer</strong>：</p><ul><li><code>period_size</code>：一次中断/唤醒处理的帧数，决定调度粒度。</li><li><code>buffer_size</code>：环形缓冲总帧数，必须 ≥ period × 2。</li><li><code>latency ≈ period_size / fs</code>（单周期）或 <code>buffer_size / fs</code>（整缓冲）。</li></ul><p><strong>hw_params（硬件约束） vs sw_params（软件行为）</strong>：</p><ul><li>hw_params：格式、声道、采样率、period、buffer、access。</li><li>sw_params：start_threshold、stop_threshold、avail_min、silence_threshold、timestamp 模式。</li></ul><p><strong>完整录音示例（RW 模式，阻塞读）</strong>：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;alsa/asoundlib.h&gt;</span></span>
<span class="token macro property"><span class="token directive-hash">#</span><span class="token directive keyword">include</span> <span class="token string">&lt;stdint.h&gt;</span></span>

<span class="token keyword">int</span> <span class="token function">capture_demo</span><span class="token punctuation">(</span><span class="token keyword">void</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token class-name">snd_pcm_t</span> <span class="token operator">*</span>pcm<span class="token punctuation">;</span>
    <span class="token class-name">snd_pcm_hw_params_t</span> <span class="token operator">*</span>hw<span class="token punctuation">;</span>
    <span class="token class-name">snd_pcm_sw_params_t</span> <span class="token operator">*</span>sw<span class="token punctuation">;</span>
    <span class="token keyword">unsigned</span> <span class="token keyword">int</span> rate <span class="token operator">=</span> <span class="token number">48000</span><span class="token punctuation">;</span>
    <span class="token class-name">snd_pcm_uframes_t</span> period <span class="token operator">=</span> <span class="token number">480</span><span class="token punctuation">,</span> buffer <span class="token operator">=</span> <span class="token number">1920</span><span class="token punctuation">;</span>
    <span class="token class-name">int16_t</span> buf<span class="token punctuation">[</span><span class="token number">480</span> <span class="token operator">*</span> <span class="token number">2</span><span class="token punctuation">]</span><span class="token punctuation">;</span>
    <span class="token keyword">int</span> rc<span class="token punctuation">;</span>

    rc <span class="token operator">=</span> <span class="token function">snd_pcm_open</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>pcm<span class="token punctuation">,</span> <span class="token string">&quot;hw:0,0&quot;</span><span class="token punctuation">,</span> SND_PCM_STREAM_CAPTURE<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>rc <span class="token operator">&lt;</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">return</span> rc<span class="token punctuation">;</span>

    <span class="token function">snd_pcm_hw_params_alloca</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>hw<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">snd_pcm_hw_params_any</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> hw<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">snd_pcm_hw_params_set_access</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> hw<span class="token punctuation">,</span> SND_PCM_ACCESS_RW_INTERLEAVED<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">snd_pcm_hw_params_set_format</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> hw<span class="token punctuation">,</span> SND_PCM_FORMAT_S16_LE<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">snd_pcm_hw_params_set_channels</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> hw<span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">snd_pcm_hw_params_set_rate_near</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> hw<span class="token punctuation">,</span> <span class="token operator">&amp;</span>rate<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">snd_pcm_hw_params_set_period_size_near</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> hw<span class="token punctuation">,</span> <span class="token operator">&amp;</span>period<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">snd_pcm_hw_params_set_buffer_size_near</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> hw<span class="token punctuation">,</span> <span class="token operator">&amp;</span>buffer<span class="token punctuation">)</span><span class="token punctuation">;</span>
    rc <span class="token operator">=</span> <span class="token function">snd_pcm_hw_params</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> hw<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span>rc <span class="token operator">&lt;</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token keyword">goto</span> out<span class="token punctuation">;</span>

    <span class="token function">snd_pcm_sw_params_alloca</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>sw<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">snd_pcm_sw_params_current</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> sw<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token comment">/* 采集：start_threshold 设为 1（也可直接 snd_pcm_start）；
     * 播放才常设为 buffer_size - period_size，攒够再启动 DMA */</span>
    <span class="token function">snd_pcm_sw_params_set_start_threshold</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> sw<span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">snd_pcm_sw_params_set_avail_min</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> sw<span class="token punctuation">,</span> period<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">snd_pcm_sw_params</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> sw<span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token function">snd_pcm_prepare</span><span class="token punctuation">(</span>pcm<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token function">snd_pcm_start</span><span class="token punctuation">(</span>pcm<span class="token punctuation">)</span><span class="token punctuation">;</span>

    <span class="token keyword">for</span> <span class="token punctuation">(</span><span class="token punctuation">;</span><span class="token punctuation">;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token class-name">snd_pcm_sframes_t</span> n <span class="token operator">=</span> <span class="token function">snd_pcm_readi</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> buf<span class="token punctuation">,</span> period<span class="token punctuation">)</span><span class="token punctuation">;</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span>n <span class="token operator">==</span> <span class="token operator">-</span>EPIPE<span class="token punctuation">)</span> <span class="token punctuation">{</span>                 <span class="token comment">/* overrun */</span>
            <span class="token function">snd_pcm_prepare</span><span class="token punctuation">(</span>pcm<span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token keyword">continue</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token keyword">if</span> <span class="token punctuation">(</span>n <span class="token operator">&lt;</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>                       <span class="token comment">/* -ESTRPIPE 等 */</span>
            <span class="token function">snd_pcm_recover</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token keyword">int</span><span class="token punctuation">)</span>n<span class="token punctuation">,</span> <span class="token number">1</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
            <span class="token keyword">continue</span><span class="token punctuation">;</span>
        <span class="token punctuation">}</span>
        <span class="token function">process</span><span class="token punctuation">(</span>buf<span class="token punctuation">,</span> <span class="token punctuation">(</span><span class="token class-name">size_t</span><span class="token punctuation">)</span>n<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
out<span class="token operator">:</span>
    <span class="token function">snd_pcm_close</span><span class="token punctuation">(</span>pcm<span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token keyword">return</span> rc<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>播放要点</strong>：</p><ul><li><code>snd_pcm_writei</code> 返回实际写入帧数，可能小于请求，要循环补齐。</li><li>首次写入前 <code>snd_pcm_prepare</code>；start_threshold 控制何时真正启动 DMA。</li><li>结束时 <code>snd_pcm_drain</code>（播完）或 <code>snd_pcm_drop</code>（立即停）。</li></ul><p><strong>xrun</strong>：</p><ul><li>capture overrun：应用读得太慢，环形缓冲被覆盖。</li><li>playback underrun：应用喂得太慢，DMA 没数据。</li><li>处理：<code>snd_pcm_prepare</code> 重新准备，或 <code>snd_pcm_recover(pcm, err, silent)</code>。</li><li>排查：看 <code>/proc/asound/card0/pcm0p/sub0/status</code> 的 <code>state: XRUN</code>、<code>avail</code>、<code>hw_ptr</code>。</li></ul><p><strong>mmap 模式</strong>（低延迟/零拷贝）：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token function">snd_pcm_mmap_begin</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> <span class="token operator">&amp;</span>areas<span class="token punctuation">,</span> <span class="token operator">&amp;</span>offset<span class="token punctuation">,</span> <span class="token operator">&amp;</span>frames<span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token comment">/* 直接读写 areas[0].addr + offset */</span>
<span class="token function">snd_pcm_mmap_commit</span><span class="token punctuation">(</span>pcm<span class="token punctuation">,</span> offset<span class="token punctuation">,</span> frames<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>时间戳</strong>：<code>snd_pcm_status_get_trigger_tstamp()</code> 获取启动时刻，<code>snd_pcm_status_get_htstamp()</code> 获取硬件时间，用于 A/V 同步和漂移测量。</p><p><strong>控制接口</strong>：</p><div class="language-c line-numbers-mode" data-ext="c"><pre class="language-c"><code><span class="token class-name">snd_ctl_t</span> <span class="token operator">*</span>ctl<span class="token punctuation">;</span>
<span class="token function">snd_ctl_open</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>ctl<span class="token punctuation">,</span> <span class="token string">&quot;hw:0&quot;</span><span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">snd_ctl_elem_list_t</span> <span class="token operator">*</span>list<span class="token punctuation">;</span>
<span class="token comment">/* 枚举、read/write，等价于 amixer */</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-5-asound-conf、插件与-ucm" tabindex="-1"><a class="header-anchor" href="#_3-5-asound-conf、插件与-ucm" aria-hidden="true">#</a> 3.5 asound.conf、插件与 UCM</h3><p>ALSA 插件层让「一个硬件」变成「多个逻辑设备」：</p><table><thead><tr><th>插件</th><th>作用</th></tr></thead><tbody><tr><td><code>plug</code></td><td>自动格式/采样率/声道转换</td></tr><tr><td><code>hw</code></td><td>直接访问硬件，无转换</td></tr><tr><td><code>dmix</code></td><td>多进程共享播放</td></tr><tr><td><code>dsnoop</code></td><td>多进程共享录音</td></tr><tr><td><code>softvol</code></td><td>软件音量</td></tr><tr><td><code>equal</code></td><td>软件 EQ</td></tr><tr><td><code>ladspa</code></td><td>挂 LADSPA 效果器</td></tr><tr><td><code>speexrate</code></td><td>重采样</td></tr><tr><td><code>file</code></td><td>写入文件（调试）</td></tr><tr><td><code>null</code></td><td>空设备（测试）</td></tr></tbody></table><p><strong>典型 <code>~/.asoundrc</code> / <code>/etc/asound.conf</code></strong>：</p><div class="language-conf line-numbers-mode" data-ext="conf"><pre class="language-conf"><code>pcm.!default {
    type plug
    slave.pcm &quot;dmix&quot;
}

pcm.dmix {
    type dmix
    ipc_key 1024
    ipc_perm 0666
    slave {
        pcm &quot;hw:0,0&quot;
        format S16_LE
        rate 48000
        channels 2
        period_size 1024
        buffer_size 8192
    }
}

pcm.dsnoop {
    type dsnoop
    ipc_key 2048
    ipc_perm 0666
    slave {
        pcm &quot;hw:0,0&quot;
        rate 48000
        channels 2
        period_size 1024
        buffer_size 8192
    }
}

pcm.mic {
    type plug
    slave.pcm &quot;dsnoop&quot;
}
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意：</p><ul><li><code>dmix</code> 要求 slave 的 format/rate/channels 固定，且硬件支持。</li><li>多进程共享时 <code>ipc_key</code> 不能冲突。</li><li><code>plug</code> 会自动做 SRC，但质量取决于 <code>speexrate</code> 等插件，低延迟场景尽量让应用直接输出硬件支持的格式。</li></ul><p><strong>UCM（Use Case Manager）</strong>：<code>/usr/share/alsa/ucm2/</code>，按 verb/device 描述「听音乐、打电话、录音」的完整 mixer 配置，PulseAudio/PipeWire 会调用。手机上比裸 asound.conf 更常见。</p><p><strong>设备管理</strong>还包括：card 热插拔（udev）、<code>alsactl</code> 保存/恢复混音状态、PulseAudio 的 card profile（<code>pactl set-card-profile</code>）、PipeWire 的 device route（<code>wpctl</code>），以及多声卡场景下的默认设备选择（<code>pactl set-default-sink</code> / <code>wpctl set-default</code>）。</p><h3 id="_3-6-上层音频服务-pulseaudio-pipewire-gstreamer" tabindex="-1"><a class="header-anchor" href="#_3-6-上层音频服务-pulseaudio-pipewire-gstreamer" aria-hidden="true">#</a> 3.6 上层音频服务：PulseAudio / PipeWire / GStreamer</h3><table><thead><tr><th>方案</th><th>定位</th><th>常用命令</th></tr></thead><tbody><tr><td><strong>PulseAudio</strong></td><td>桌面/嵌入式声音服务器，混音、路由、网络音频</td><td><code>pactl info</code>、<code>pactl list short sinks</code>、<code>pacmd list-sinks</code></td></tr><tr><td><strong>PipeWire</strong></td><td>新一代多媒体图（音频+视频），低延迟，兼容 PulseAudio/JACK</td><td><code>pw-top</code>、<code>pw-cli</code>、<code>wpctl status</code>、<code>wpctl set-default</code></td></tr><tr><td><strong>GStreamer</strong></td><td>流媒体管线框架</td><td><code>gst-launch-1.0 alsasrc ! audioconvert ! alsasink</code></td></tr><tr><td><strong>tinyalsa</strong></td><td>Android/嵌入式轻量库，直接操作 <code>/dev/snd</code></td><td><code>tinyplay</code>、<code>tinycap</code>、<code>tinymix</code>、<code>tinypcminfo</code></td></tr><tr><td><strong>Android AudioFlinger</strong></td><td>Android 音频 HAL 之上，FastMixer/offload</td><td><code>dumpsys media.audio_flinger</code></td></tr></tbody></table><p><strong>什么时候绕过声音服务器</strong>：</p><ul><li>需要极低延迟（&lt; 10 ms）或精确时钟：直接 <code>hw:</code> + mmap。</li><li>需要独占设备/专业音频：ALSA 直连或 JACK。</li><li>语音前端：通常直接读 ALSA，避免 PulseAudio 的额外缓冲和重采样。</li></ul><p><strong>PipeWire 的 quantum</strong>：默认 1024 帧（48 kHz 下约 21 ms），低延迟可调到 256/128；<code>pw-metadata -n settings 0 clock.quantum 256</code>。</p><h3 id="_3-7-调试命令与-proc-速查" tabindex="-1"><a class="header-anchor" href="#_3-7-调试命令与-proc-速查" aria-hidden="true">#</a> 3.7 调试命令与 /proc 速查</h3><p><strong>设备与能力</strong>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">cat</span> /proc/asound/cards                 <span class="token comment"># 有哪些声卡</span>
<span class="token function">cat</span> /proc/asound/devices               <span class="token comment"># pcm/control 设备号</span>
aplay <span class="token parameter variable">-l</span>                               <span class="token comment"># 播放设备列表</span>
aplay <span class="token parameter variable">-L</span>                               <span class="token comment"># 含插件的逻辑设备</span>
arecord <span class="token parameter variable">-l</span>                             <span class="token comment"># 录音设备列表</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>当前参数与状态</strong>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">cat</span> /proc/asound/card0/pcm0p/sub0/hw_params
<span class="token function">cat</span> /proc/asound/card0/pcm0p/sub0/status
<span class="token function">cat</span> /proc/asound/card0/pcm0c/sub0/hw_params
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>status</code> 里重点看：<code>state</code>（RUNNING/XRUN）、<code>owner_pid</code>、<code>hw_ptr</code>/<code>appl_ptr</code>、<code>avail</code>。</p><p><strong>播放/录音自检</strong>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>speaker-test <span class="token parameter variable">-D</span> hw:0,0 <span class="token parameter variable">-c</span> <span class="token number">2</span> <span class="token parameter variable">-t</span> sine <span class="token parameter variable">-f</span> <span class="token number">1000</span> <span class="token parameter variable">-l</span> <span class="token number">1</span>
arecord <span class="token parameter variable">-D</span> hw:0,0 <span class="token parameter variable">-f</span> S16_LE <span class="token parameter variable">-r</span> <span class="token number">48000</span> <span class="token parameter variable">-c</span> <span class="token number">2</span> <span class="token parameter variable">-d</span> <span class="token number">5</span> /tmp/test.wav
aplay   <span class="token parameter variable">-D</span> hw:0,0 <span class="token parameter variable">-f</span> S16_LE <span class="token parameter variable">-r</span> <span class="token number">48000</span> <span class="token parameter variable">-c</span> <span class="token number">2</span> /tmp/test.wav
aplay <span class="token parameter variable">-D</span> hw:0,0 --dump-hw-params /tmp/test.wav   <span class="token comment"># 打印支持的参数范围</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>Mixer</strong>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>amixer <span class="token parameter variable">-c</span> <span class="token number">0</span> scontrols
amixer <span class="token parameter variable">-c</span> <span class="token number">0</span> contents
amixer <span class="token parameter variable">-c</span> <span class="token number">0</span> sset <span class="token string">&#39;Master&#39;</span> <span class="token number">80</span>%
amixer <span class="token parameter variable">-c</span> <span class="token number">0</span> sset <span class="token string">&#39;Capture&#39;</span> <span class="token number">70</span>% cap
alsactl store
alsactl restore
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>驱动/设备树</strong>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">dmesg</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-iE</span> <span class="token string">&#39;asoc|snd|codec|i2s&#39;</span>
<span class="token function">cat</span> /sys/kernel/debug/asoc/cards
<span class="token function">cat</span> /sys/kernel/debug/asoc/<span class="token operator">&lt;</span>card<span class="token operator">&gt;</span>/dapm
<span class="token function">cat</span> /sys/kernel/debug/clk/clk_summary <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-i</span> mclk
<span class="token function">cat</span> /proc/interrupts <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-i</span> i2s
i2cdetect <span class="token parameter variable">-y</span> <span class="token number">0</span>                          <span class="token comment"># codec 是否在总线上</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>跟踪系统调用/延迟</strong>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">strace</span> <span class="token parameter variable">-f</span> <span class="token parameter variable">-e</span> <span class="token assign-left variable">trace</span><span class="token operator">=</span>ioctl,read,write <span class="token parameter variable">-T</span> arecord <span class="token parameter variable">-D</span> hw:0,0 <span class="token parameter variable">-f</span> S16_LE <span class="token parameter variable">-r</span> <span class="token number">48000</span> <span class="token parameter variable">-d</span> <span class="token number">2</span> /tmp/a.wav
latmus                                   <span class="token comment"># alsa-tools，测往返延迟</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>典型排查顺序</strong>（没声音）：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>1. /proc/asound/cards 有没有声卡
2. dmesg 有没有 probe 失败 / clock 错误
3. amixer 音量、mute、DAPM 路径
4. aplay -D hw:0,0 是否能播（绕过插件）
5. /proc/.../hw_params 是否 RUNNING
6. 示波器/逻辑分析仪看 BCLK/LRCLK/DATA
7. codec 寄存器（i2cget）与 MCLK
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr>`,89),v=s("strong",null,"系列导航",-1),b=s("strong",null,"下一篇",-1);function _(g,h){const a=c("RouterLink");return o(),i("div",null,[s("blockquote",null,[s("p",null,[n("本文是「设备端音频与语音处理」系列第 3 篇（共 7 篇）。系列导览："),e(a,{to:"/source-study/audio/"},{default:t(()=>[n("从 pipeline 到 Linux 音频栈")]),_:1}),n("。")])]),r,k,l(" more "),m,s("p",null,[v,n("："),e(a,{to:"/source-study/audio/"},{default:t(()=>[n("系列导览")]),_:1}),n(" · "),b,n("："),e(a,{to:"/source-study/audio/04-embedded-speech-architecture.html"},{default:t(()=>[n("设备端音频（四）：端侧语音架构与性能调优")]),_:1})])])}const y=p(u,[["render",_],["__file","03-linux-audio-stack.html.vue"]]);export{y as default};
